-- Run the entire script in SSMS against the target TEST database after applying migrations.
-- DESTRUCTIVE: every run replaces all ORP application data, including users and audit history.
-- Stop the application and other writers before running. Schema and migration history are preserved.
-- All IDs are generated by SQL Server. No database/schema creation or migration is performed.
-- Demo scenarios (not a production routing matrix):
--   CS/TFO Incoming: two immediate confirmations; demo TFO Outgoing: one, same actor allowed,
--     retain assignment until completion; any scoped authorised user can undo the first.
--   DC MT671: one immediate confirmation, ordinary Undo disabled.
--   View-only workflow is available; PDF completion remains outside ORP confirmation.
--   Reject is disabled for these demo workflows.
-- Global administrators retain their exception when no review is active.
-- All 100 messages start New. Use the application to assign, review and inspect the audit.
SET NOCOUNT ON;
SET XACT_ABORT ON;
-- Required when writing tables with filtered indexes, including through sqlcmd.
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;

IF OBJECT_ID(N'orp.AuditEvents', N'U') IS NULL
    THROW 51000, 'Apply ORP migrations before loading test data.', 1;
IF COL_LENGTH(N'orp.WorkflowDefinitions', N'UndoApprovalMode') IS NULL
    OR COL_LENGTH(N'orp.WorkflowDefinitions', N'UndoActorMode') IS NULL
    OR COL_LENGTH(N'orp.WorkflowDefinitions', N'UndoActiveReviewMode') IS NULL
    THROW 51000, 'Apply AddWorkflowUndoPolicy before loading test data.', 1;
IF COL_LENGTH(N'orp.WorkflowDefinitions', N'Code') IS NULL
    THROW 51000, 'Apply reusable workflow migration before loading test data.', 1;
IF COL_LENGTH(N'orp.SwiftMessages', N'FilePath') IS NULL
    THROW 51000, 'Apply ImportSaaMessages before loading test data.', 1;
IF COL_LENGTH(N'orp.WorkflowDefinitions', N'ConfirmationMode') IS NULL
    THROW 51000, 'Apply ConfigureConfirmations before loading test data.', 1;
IF @@TRANCOUNT <> 0
    THROW 51000, 'Run this script outside an existing transaction.', 1;

BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @lockResult int;
    EXEC @lockResult = sys.sp_getapplock @Resource=N'orp-swift-sync',
        @LockMode=N'Exclusive', @LockOwner=N'Transaction', @LockTimeout=0;
    IF @lockResult < 0 THROW 51000, 'Another ORP data writer is active.', 1;

    -- 1. Reset demo data. Cleanup and loading roll back together on any failure.
    -- Delete dependent rows first; preserve the schema and EF migration history.
    DELETE FROM [orp].[AuditEvents];
    DELETE FROM [orp].[AccessAuditEvents];
    DELETE FROM [orp].[Reviews];
    DELETE FROM [orp].[Assignments];
    DELETE FROM [orp].[MessageDepartments];
    DELETE FROM [orp].[Messages];
    DELETE FROM [orp].[SwiftMessages];
    IF OBJECT_ID(N'orp.IgnoredImportFiles', N'U') IS NOT NULL
        DELETE FROM [orp].[IgnoredImportFiles];
    DELETE FROM [orp].[DepartmentRoutingRules];
    DELETE FROM [orp].[WorkflowSteps];
    DELETE FROM [orp].[WorkflowDefinitions];
    DELETE FROM [orp].[UserRoles];
    DELETE FROM [orp].[RolePermissions];
    DELETE FROM [orp].[Users];
    DELETE FROM [orp].[Roles];
    DELETE FROM [orp].[Permissions];
    DELETE FROM [orp].[Branches];
    DELETE FROM [orp].[Departments];

    -- 2. Reference data and role permissions.
    INSERT INTO [orp].[Branches] ([Name]) VALUES (N'London');
    INSERT INTO [orp].[Departments] ([Name]) VALUES (N'CS'),(N'TFO'),(N'DC');

    INSERT INTO [orp].[Permissions] ([Name]) VALUES
        (N'message.view'),(N'message.assign'),(N'review.level1'),(N'review.level2'),
        (N'review.level3'),(N'review.undo'),(N'audit.view'),(N'workflow.manage');

    INSERT INTO [orp].[Roles] ([Name]) VALUES (N'Reviewer'),(N'Operations manager');

    INSERT INTO [orp].[RolePermissions] ([RoleId],[PermissionId])
    SELECT r.[Id],p.[Id] FROM [orp].[Roles] r CROSS JOIN [orp].[Permissions] p
    WHERE r.[Name]=N'Operations manager'
        OR (r.[Name]=N'Reviewer'
            AND p.[Name] IN (N'message.view',N'message.assign',N'review.level1',
                N'review.level2',N'review.level3',N'review.undo',N'audit.view'));

    -- 3. Users and exact branch/department scopes.
    DECLARE @users TABLE ([UserName] nvarchar(80),[DisplayName] nvarchar(160),
        [RoleName] nvarchar(80),[IsAdmin] bit,[DepartmentName] nvarchar(80));
    INSERT INTO @users VALUES
        (N'cs.reviewer1',N'CS Reviewer 1',N'Reviewer',0,N'CS'),
        (N'cs.reviewer2',N'CS Reviewer 2',N'Reviewer',0,N'CS'),
        (N'tfo.reviewer1',N'TFO Reviewer 1',N'Reviewer',0,N'TFO'),
        (N'tfo.reviewer2',N'TFO Reviewer 2',N'Reviewer',0,N'TFO'),
        (N'dc.reviewer1',N'DC Reviewer 1',N'Reviewer',0,N'DC'),
        (N'dc.reviewer2',N'DC Reviewer 2',N'Reviewer',0,N'DC'),
        (N'admin',N'Administrator',N'Operations manager',1,NULL);

    INSERT INTO [orp].[Users] ([UserName],[DisplayName],[IsGlobalAdministrator])
    SELECT [UserName],[DisplayName],[IsAdmin] FROM @users;

    INSERT INTO [orp].[UserRoles] ([UserId],[BranchId],[DepartmentId],[RoleId])
    SELECT u.[Id],b.[Id],d.[Id],r.[Id] FROM @users v
    JOIN [orp].[Users] u ON u.[UserName]=v.[UserName]
    JOIN [orp].[Roles] r ON r.[Name]=v.[RoleName]
    CROSS JOIN [orp].[Branches] b
    CROSS JOIN [orp].[Departments] d
    WHERE v.[IsAdmin]=1 OR d.[Name]=v.[DepartmentName];

    DECLARE @Profiles TABLE (Code nvarchar(100), Name nvarchar(100), Levels int);
    INSERT INTO @Profiles VALUES
        (N'VIEW_ONLY',N'View only',0),
        (N'SINGLE_CONFIRMATION',N'Single confirmation',1),
        (N'DOUBLE_CONFIRMATION',N'Double confirmation',2);
    INSERT INTO orp.WorkflowDefinitions
        (Code,Name,IsActive,ConfirmationMode,ConfirmationActorMode,AllowReviewerReuse,AssignmentRetentionMode,RejectAllowed,
         UndoApprovalMode,UndoActorMode,UndoActiveReviewMode)
    SELECT p.Code,p.Name,1,CASE WHEN p.Levels=0 THEN 2 ELSE 1 END,1,1,1,0,
        CASE WHEN p.Levels=2 THEN 1 ELSE 0 END,1,CASE WHEN p.Levels=2 THEN 1 ELSE 0 END
    FROM @Profiles p WHERE NOT EXISTS (SELECT 1 FROM orp.WorkflowDefinitions w WHERE w.Code=p.Code);
    INSERT INTO orp.WorkflowSteps (WorkflowDefinitionId,[Order],ReviewLevel,Required)
    SELECT w.Id,n.Level,n.Level,1 FROM @Profiles p JOIN orp.WorkflowDefinitions w ON w.Code=p.Code
    CROSS JOIN (VALUES (1),(2)) n(Level)
    WHERE n.Level<=p.Levels AND NOT EXISTS (SELECT 1 FROM orp.WorkflowSteps s WHERE s.WorkflowDefinitionId=w.Id AND s.ReviewLevel=n.Level);
    IF EXISTS (SELECT 1 FROM @Profiles p JOIN orp.WorkflowDefinitions w ON w.Code=p.Code
        WHERE w.IsActive<>1 OR w.ConfirmationMode<>CASE WHEN p.Levels=0 THEN 2 ELSE 1 END
        OR w.ConfirmationActorMode<>1 OR w.AllowReviewerReuse<>1 OR w.AssignmentRetentionMode<>1 OR w.RejectAllowed<>0
        OR w.UndoApprovalMode<>CASE WHEN p.Levels=2 THEN 1 ELSE 0 END OR w.UndoActorMode<>1
        OR w.UndoActiveReviewMode<>CASE WHEN p.Levels=2 THEN 1 ELSE 0 END
        OR (SELECT COUNT(*) FROM orp.WorkflowSteps s WHERE s.WorkflowDefinitionId=w.Id)<>p.Levels
        OR EXISTS (SELECT 1 FROM orp.WorkflowSteps s WHERE s.WorkflowDefinitionId=w.Id AND (s.Required<>1 OR s.[Order]<>s.ReviewLevel)))
        THROW 51000, 'Existing common workflow conflicts with approved policy.', 1;

    DECLARE @Incoming int=1, @Outgoing int=2;
    DECLARE @workflows TABLE (Ordinal int, MessageType nvarchar(20), Name nvarchar(100), DepartmentName nvarchar(80), Direction int, Code nvarchar(100));
    INSERT INTO @workflows VALUES
        (0,N'MT199',N'CS example',N'CS',1,N'DOUBLE_CONFIRMATION'),
        (1,N'MT299',N'TFO example',N'TFO',1,N'DOUBLE_CONFIRMATION'),
        (2,N'MT671',N'DC example',N'DC',1,N'SINGLE_CONFIRMATION'),
        (3,N'MT299',N'TFO outgoing example',N'TFO',2,N'SINGLE_CONFIRMATION');
    INSERT INTO orp.DepartmentRoutingRules
        (DepartmentId,Direction,MatchKind,MessageTypePattern,IsActive,SourceFile,SourceSheet,SourceRow,WorkflowDefinitionId)
    SELECT d.Id,v.Direction,1,v.MessageType,1,N'demo-seed',N'examples',v.Ordinal+1,w.Id
    FROM @workflows v JOIN orp.Departments d ON d.Name=v.DepartmentName
    JOIN orp.WorkflowDefinitions w ON w.Code=v.Code;

    -- 5. Messages: preserve the first 75 Incoming examples, then add 25 Outgoing examples.
    -- TEST-00001 = two-step / London; TEST-00002 = two-step / London;
    -- TEST-00003 = single / London. TEST-00076 = Outgoing / TFO / London. Times cover the last 100 hours.
    DECLARE @now datetimeoffset = SYSUTCDATETIME();
    DECLARE @messageCount int = 100;
    ;WITH numbers AS (SELECT 1 AS n UNION ALL SELECT n+1 FROM numbers WHERE n<@messageCount)
    INSERT INTO [orp].[SwiftMessages]
        ([Branch],[MessageType],[ReferenceId],[Direction],[Sender],[Receiver],[Host],[Time],
         [Body],[FileName],[FilePath],[ContentHash])
    SELECT b.[Name],v.[MessageType],CONCAT(N'TEST-',RIGHT(CONCAT(N'00000',n),5)),v.[Direction],
        N'TESTGB2LXXX',N'DEMOGB2LXXX',N'seed',CAST(DATEADD(hour,n-@messageCount,@now) AS datetime2),
        body.[Value],CONCAT(N'TEST-',RIGHT(CONCAT(N'00000',n),5),N'.prt'),
        CONCAT(N'demo/TEST-',RIGHT(CONCAT(N'00000',n),5),N'.prt'),
        CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),body.[Value])),2)
    FROM numbers
    JOIN @workflows v ON v.[Ordinal]=CASE WHEN n<=75 THEN (n-1)%3 ELSE 3 END
    JOIN [orp].[Departments] d ON d.[Name]=v.[DepartmentName]
    JOIN [orp].[Branches] b ON b.[Name]=N'London'
    CROSS APPLY (SELECT CONCAT(N'{1:F01TESTGB2LXXXX0000000000}{2:I',
        SUBSTRING(v.[MessageType],3,3),N'DEMOGB2LXXXXN}{4:',CHAR(10),N':20:TEST-',n,
        CHAR(10),N':79:SYNTHETIC TEST MESSAGE - ',v.[Name],CHAR(10),N'-}')) body([Value]);

    INSERT INTO [orp].[Messages]
        ([MessageId],[State],[CurrentAssigneeId],[WorkflowDefinitionId],[BranchId],[ReceivedAt])
    SELECT s.[MessageId],N'New',NULL,w.[Id],b.[Id],TODATETIMEOFFSET(s.[Time], '+00:00')
    FROM [orp].[SwiftMessages] s
    JOIN [orp].[Branches] b ON b.[Name]=s.[Branch]
    JOIN @workflows v ON v.MessageType=s.MessageType AND v.Direction=s.Direction
    JOIN orp.WorkflowDefinitions w ON w.Code=v.Code;
    INSERT INTO orp.MessageDepartments (MessageId,DepartmentId,CanProcess)
    SELECT m.MessageId,d.Id,1 FROM orp.Messages m JOIN orp.SwiftMessages s ON s.MessageId=m.MessageId
    JOIN @workflows v ON v.MessageType=s.MessageType AND v.Direction=s.Direction
    JOIN orp.Departments d ON d.Name=v.DepartmentName;

    -- 6. Initial audit trail; later decisions are recorded by the application.
    INSERT INTO [orp].[AuditEvents]
        ([MessageId],[EventType],[UserId],[Timestamp],[OldState],[NewState],[DetailsJson],[CorrelationId],[ReviewId])
    SELECT [MessageId],N'MessageRegistered',NULL,@now,NULL,N'New',
        CONCAT(N'{"workflowDefinitionId":',[WorkflowDefinitionId],N'}'),N'sql-test-seed-v2',NULL
    FROM [orp].[Messages];

    COMMIT;
    PRINT 'Loaded London, 7 users, 3 common workflows and 100 unassigned demo messages.';
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK;
    THROW;
END CATCH;
